# ============================================================== API
EPS = [("GET /v1/waqt", "Everything: day boundary, reading, six events, next event, Hijri date. Powers every live component on this site."),
       ("GET /v1/day", "The day boundary only."), ("GET /v1/events", "The six events only (no calendar)."),
       ("GET /v1/hijri", "Calendar lookup; no location needed."), ("GET /v1/calendar", "Discovery: the available calendar providers."),
       ("GET /v1/location", "Timezone and local civil-date resolution."), ("GET /v1/conversions", "Gregorian ↔ Hijri, either direction."),
       ("GET /v1/version", "Every version axis: spec, engine, API, conformance."), ("GET /v1/health", "Component status."),
       ("/v1/schedule/*", "Snapshot, span and rule resolution (windows, deadlines, “30 minutes before Maghrib”)."), ("/v1/institutional/*", "Islamic week, fiscal year, academic year.")]
rows = "".join(f'<tr><td class="text-primary-container whitespace-nowrap">{a}</td><td class="text-on-surface-variant font-body-md" style="font-family:Inter,sans-serif">{b}</td></tr>' for a, b in EPS)
api_body = hero("API", "Build with the Waqt API", "A versioned, language-independent HTTP contract. Every response is one envelope — <code>{meta, data, error}</code> — with exactly one of <code>data</code> and <code>error</code> set.") \
  + wrap(f'''<div class="flex flex-wrap gap-3 mb-8"><a class="btn" data-api-docs href="#">Interactive API docs</a><a class="btn ghost" data-openapi href="#">OpenAPI JSON</a><a class="btn ghost" href="live-demo.html">Live demo</a></div>
<div class="grid lg:grid-cols-2 gap-6"><div class="{PANEL}"><p class="{MICRO} mb-3">API status</p><div id="api-status" class="text-body-md text-on-surface-variant" role="status">Checking…</div></div>
<div class="{PANEL}"><p class="{MICRO} mb-3">Request tester</p><div class="field-row"><div class="field"><label for="t-ep">Endpoint</label><select id="t-ep"><option value="/v1/waqt">/v1/waqt</option><option value="/v1/day">/v1/day</option><option value="/v1/events">/v1/events</option><option value="/v1/calendar">/v1/calendar</option><option value="/v1/version">/v1/version</option><option value="/v1/health">/v1/health</option></select></div><button class="btn" id="t-run" type="button">Send request</button></div><p id="t-meta" class="mt-3 text-[12px] text-on-surface-variant font-label-sm" role="status"></p></div></div>
<pre class="code mt-6" id="t-out" tabindex="0" aria-label="Response" style="max-height:420px">Press “Send request”.</pre>''', border=False, cls="pb-10") \
  + wrap(h2("Endpoints", "", "Reference") + f'<div class="table-scroll bg-surface-container-low"><table class="data"><caption class="vh">Waqt API endpoints</caption><thead><tr><th scope="col">Endpoint</th><th scope="col">Returns</th></tr></thead><tbody>{rows}</tbody></table></div><p class="mt-3 text-[12px] text-on-surface-variant">Schemas, error codes, units and versioning policy: <code>docs/API.md</code> in the repository.</p>') \
  + wrap(h2("A complete call", "", "Example") + f'''<div class="grid lg:grid-cols-2 gap-8"><div><div class="tabs" role="tablist" aria-label="Language"><button role="tab" aria-selected="true" data-tab="curl">curl</button><button role="tab" aria-selected="false" data-tab="js">JavaScript</button><button role="tab" aria-selected="false" data-tab="py">Python (stdlib)</button></div><pre class="code" id="api-snippet" tabindex="0" aria-label="Code example"></pre></div>
<dl class="kv"><dt>day.maghrib_open / maghrib_close</dt><dd>Exact instants bounding the day; <code>length_si_seconds</code> is its real length.</dd><dt>waqt.reading</dt><dd>Seconds and HH:MM:SS since the opening Maghrib; may pass 24:00:00.</dd><dt>events[]</dt><dd>Fajr, sunrise, Dhuhr, Asr, Maghrib, Isha: an instant and a reading each.</dd><dt>next_event</dt><dd>The earliest event after <code>instant</code>, with a ready-made countdown.</dd><dt>status</dt><dd><code>OK</code>, or an explicit <code>UNDEFINED</code> with a reason.</dd><dt>computation</dt><dd>Engine, accuracy level, timescale model and ΔT used.</dd></dl></div>''') \
  + wrap(h2("Client libraries and conformance", "", "Ecosystem") + f'''<div class="grid lg:grid-cols-2 gap-6"><div class="{PANEL}"><p class="{MICRO} mb-3">In the repository</p><div class="table-scroll"><table class="data"><caption class="vh">Libraries</caption><thead><tr><th scope="col">Package</th><th scope="col">Path</th><th scope="col">Status</th></tr></thead><tbody><tr><td>waqt-client (Python)</td><td>sdks/python</td><td>packaged; registry publication unconfirmed</td></tr><tr><td>waqt-client (JavaScript)</td><td>sdks/js/waqt-client</td><td>packaged; registry publication unconfirmed</td></tr><tr><td>waqt-core</td><td>core/</td><td>computation layer, installable alone</td></tr><tr><td>waqt-local</td><td>local/</td><td>embeddable, no server</td></tr></tbody></table></div></div>
<div class="{PANEL}"><p class="{MICRO} mb-3">Conformance contract</p><div class="flex justify-between gap-4 py-1.5 border-b border-outline-variant/30 font-label-sm text-[12px]"><span class="text-on-surface-variant">Contract version</span><span>{_CV} (draft)</span></div><p class="mt-3 text-body-md text-on-surface-variant">Version 2.0.0, <b class="text-on-surface">draft — not released</b>. Portable test vectors and a harness live in <code>conformance/</code>. The reference implementation and an independent clean-room engine are both recorded with <b class="text-on-surface">0 known failures</b> against the current vectors, and the contract’s decision records await ratification. This site contains no calculation of its own.</p></div></div>''')
page("api.html", "API", "The Waqt HTTP API: endpoints, response model, a live request tester and conformance status.", "api", api_body, CORE, ["pages/api"])

# ============================================================== APPLICATIONS
def app_card(image, title, kind, text, facts):
    li = "".join(f"<li>{f}</li>" for f in facts)
    return f'''<article data-app-card class="bg-surface-container-low flex flex-col">{img(image, title + " (concept art)", ratio="aspect-video")}<div class="p-5 flex flex-col gap-2 flex-1"><div class="flex justify-between items-start gap-2"><h3 class="font-headline-sm text-[16px]">{title}</h3>{badge(kind)}</div><p class="text-body-md text-on-surface-variant">{text}</p><ul class="mt-auto pt-3 space-y-1 font-label-sm text-[11px] text-on-surface-variant list-none p-0">{li}</ul></div></article>'''
legend = f'''<div class="grid md:grid-cols-3 gap-4" role="list"><div role="listitem" class="{PANEL}">{badge("real")}<p class="mt-3 text-body-md text-on-surface-variant">Exists and runs: you can use it or open it now — the API, the reference viewer, the CLI and the live visualisations on this site.</p></div><div role="listitem" class="{PANEL}">{badge("concept")}<p class="mt-3 text-body-md text-on-surface-variant">A designed application. The preview on this page is real software fed by real (or labelled demo) data; no product or device is deployed.</p></div><div role="listitem" class="{PANEL}">{badge("future")}<p class="mt-3 text-body-md text-on-surface-variant">An idea the API enables. Not designed in detail and not built.</p></div></div>'''
previews = f'''<div id="apps-live"><div id="apps-banner" class="mb-4"></div><div class="grid lg:grid-cols-2 gap-6">
<div class="{PANEL}"><div class="flex justify-between items-center mb-4"><h3 class="font-headline-sm text-[16px]">Circular Waqt clock</h3>{badge("real")}</div><div id="apps-clock"></div></div>
<div class="{PANEL}"><div class="flex justify-between items-center mb-4"><h3 class="font-headline-sm text-[16px]">Mosque Waqt clock</h3>{badge("concept")}</div><div id="apps-mosque"></div></div>
<div class="{PANEL}"><div class="flex justify-between items-center mb-4"><h3 class="font-headline-sm text-[16px]">Waqt smartwatch</h3>{badge("concept")}</div><div id="apps-watch"></div></div>
<div class="{PANEL}"><div class="flex justify-between items-center mb-4"><h3 class="font-headline-sm text-[16px]">Waqt day vs midnight day</h3>{badge("real")}</div><div id="apps-day"></div></div></div></div>'''
eco2 = f'''<div class="grid lg:grid-cols-2 gap-8 items-center"><div class="eco" role="img" aria-label="Diagram: the Waqt API feeds a mosque clock, smartwatch, mobile app, institution calendar, dashboard and developer application"><div class="core">WAQT API</div><div class="arrow" aria-hidden="true">↓</div><div class="grid grid-cols-2 sm:grid-cols-3 gap-2 w-full"><div class="leaf">Mosque clock {badge("concept")}</div><div class="leaf">Smartwatch {badge("concept")}</div><div class="leaf">Mobile {badge("concept")}</div><div class="leaf">Institution {badge("concept")}</div><div class="leaf">Dashboard {badge("concept")}</div><div class="leaf">Your application {badge("real")}</div></div></div>{img("api-ecosystem", "Concept render: devices connected to a central Waqt clock")}</div>'''
gallery = '<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">' + "".join([
 app_card("mosque-wall-clock", "Mosque Waqt Clock", "concept", "A prayer-hall wall display: the Waqt reading, the next event with a countdown and the Maghrib boundary.", ["Data: /v1/waqt (real)", "Status: no deployed device"]),
 app_card("smartwatch", "Waqt Smartwatch", "concept", "A watch face built from the same event timeline as the circular clock — no separate calculations.", ["Data: /v1/waqt (real)", "Status: no watch app exists"]),
 app_card("mobile-app", "Waqt Mobile App", "concept", "A phone-first day ring, next event and Hijri date, with location from the device.", ["Data: /v1/waqt (real)", "Status: no mobile app published"]),
 app_card("circular-clock", "Circular Waqt Clock", "real", "A reusable SVG component on this site, drawn from API data with a text equivalent and keyboard navigation.", ["Data: /v1/waqt (real)", 'Where: <a class="text-primary-container" href="index.html">home</a>, above, <a class="text-primary-container" href="lab.html">Lab</a>']),
 app_card("vs-midnight", "Waqt Day vs Midnight Day", "real", "Two temporal models side by side using the real event times and the real day length.", ["Data: /v1/waqt (real)", 'Where: <a class="text-primary-container" href="lab.html#compare">Lab, step 04</a>']),
 app_card("api-ecosystem", "API → Applications", "real", "The core and scheduling endpoints, institutional endpoints, a CLI and a reference web viewer.", ['Where: <a class="text-primary-container" href="api.html">API</a>, <a class="text-primary-container" href="live-demo.html">Live demo</a>']),
 app_card("institutional-calendar", "Institutional Calendar", "concept", "A wall calendar for schools, offices or mosques: Islamic week, fiscal and academic years from configurable rules.", ["Backend: /v1/institutional/* exist (real)", "Status: no calendar product"]),
 app_card("developer-api", "Developer Dashboard", "concept", "A console for exploring responses, events and timelines while integrating. Today: interactive API docs and the live demo.", ["Status: no dashboard product"]),
 app_card("global-location", "Location / Travel", "concept", "See the Waqt day change as you move — the boundary is Maghrib at your location.", ["Backend: /v1/waqt, /v1/location (real)", 'Try: <a class="text-primary-container" href="lab.html#reset">Lab, step 02</a>'])]) + "</div>"
future = f'''<div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">{"".join(f'<figure class="m-0 bg-surface-container-low">{img(n, a)}<figcaption class="p-3 text-[13px] text-on-surface-variant"><b class="text-on-surface">{t}</b> — {d} {badge("future")}</figcaption></figure>' for n, a, t, d in [("smart-home", "Concept render of a living room with a Waqt display", "Smart home", "ambient Waqt on a wall or tablet."), ("public-display", "Concept render of a public display in an airport showing Waqt", "Public displays", "transport hubs and shared spaces."), ("astronomy-research", "Concept render of an observatory", "Research", "independent astronomical verification."), ("human-time", "Concept render of a person looking at a watch at dusk", "Wearables", "a glanceable day and next event.")])}</div>
<div class="mt-8 bg-surface-container-low p-6 text-body-md"><b>Have an idea for an application?</b> <a data-idea class="text-primary-container hover:underline" href="mailto:waqtapi@gmail.com">Send an Idea</a> — we read every one.</div>'''
apps_body = hero("Applications", "Applications &amp; possibilities", "Waqt is infrastructure first. Here is what exists, what is a design concept, and what is still an idea — we never present a mockup as a deployed product.") \
  + wrap(legend + f'<p class="mt-4 notice info">New: the <a class="text-primary-container" href="lab.html">Waqt Experience Lab</a> — five interactive demonstrations, from dragging through a Waqt day to building your own application.</p>', border=False, cls="pb-10") \
  + wrap(h2("Live previews", "Four presentations of one API response.", "Real data", hid="h-live") + previews) \
  + wrap(h2("One API, many applications", "", "Architecture", hid="h-eco") + eco2) \
  + wrap(h2("Application gallery", "", "Catalogue", hid="h-gallery") + gallery) \
  + wrap(h2("Future concepts", "Ideas the API makes possible. None is built.", "Horizon", hid="h-future") + future)
page("applications.html", "Applications", "Waqt applications: what is real, what is a concept, and what is still a future idea.", "apps", apps_body, LIVE, ["pages/applications"])

# ============================================================== LAB
def step(num, sid, title, sub, inner):
    return f'<section id="{sid}" class="lab-step border-t border-outline-variant/30 py-12" aria-labelledby="h-{sid}"><div class="max-w-[1400px] mx-auto px-4 lg:px-8 grid md:grid-cols-[72px_1fr] gap-4"><div class="font-headline-lg text-[40px] text-secondary/60" aria-hidden="true">{num}</div><div><h2 id="h-{sid}" class="font-headline-md text-[24px]">{title}</h2><p class="mt-1 mb-6 text-body-md text-on-surface-variant">{sub}</p>{inner}</div></div></section>'
lab_body = hero("Experience Lab", "Waqt, experienced — not just explained", "Five short demonstrations. Each is driven by the real Waqt API; if it cannot be reached they switch to a frozen, labelled sample. Nothing here calculates Waqt in your browser.") \
  + wrap('<div id="lab-banner" class="mb-4"></div><nav aria-label="Lab steps" class="flex flex-wrap gap-2">' + "".join(f'<a class="btn ghost small" href="#{i}">{t}</a>' for i, t in [("clock", "01 The Waqt Clock"), ("reset", "02 Maghrib Reset"), ("next", "03 Next Event"), ("compare", "04 Waqt vs Midnight"), ("build", "05 Build an Application")]) + '</nav>', border=False, cls="pb-6") \
  + step("01", "clock", "The Waqt Clock — drag through the day", "Move the slider from one Maghrib to the next; markers are the events the API returned for this Waqt day.", f'''<div class="grid lg:grid-cols-2 gap-8 items-start"><div id="lab-clock"></div><div><div class="field"><label for="scrub">Position in the Waqt day</label><input id="scrub" type="range" min="0" max="1000" value="0" aria-describedby="scrub-out"></div><div class="{PANEL} mt-4" id="scrub-out" aria-live="polite"></div><p class="mt-3 text-[12px] text-on-surface-variant"><span class="badge demo">SCRUB PREVIEW</span> The slider picks a position on the day; the reading shown is that position’s elapsed time since Maghrib, not a live reading.</p></div></div>''') \
  + step("02", "reset", "Maghrib Reset — move the place and the date", "Pick a place and a date; the API says where that day’s Maghrib boundary falls. Watch it move.", f'''<form id="reset-form" class="field-row" onsubmit="return false"><div class="field"><label for="reset-place">Place</label><select id="reset-place"><option value="9.0192,38.7525">Addis Ababa</option><option value="21.4225,39.8262">Makkah</option><option value="51.5074,-0.1278">London</option><option value="-6.2088,106.8456">Jakarta</option><option value="64.1466,-21.9426">Reykjavík</option></select></div><div class="field"><label for="reset-date">Date (UTC, taken at 12:00)</label><input id="reset-date" type="date"></div><button class="btn" id="reset-go" type="button">Ask the API</button></form><div id="reset-status" class="my-3 text-[13px] text-on-surface-variant" role="status"></div><div class="table-scroll bg-surface-container-low"><table class="data" id="reset-table" hidden><caption class="vh">Maghrib boundaries returned by the API</caption><thead><tr><th scope="col">Place</th><th scope="col">Date</th><th scope="col">Maghrib opens (local)</th><th scope="col">Next Maghrib (local)</th><th scope="col">Day length</th></tr></thead><tbody id="reset-rows"></tbody></table></div>''') \
  + step("03", "next", "Next Event — watch the countdown move", "Real time is slow, so this plays the day back faster. The events are the API’s; only the passage of time is accelerated.", f'''<div class="grid lg:grid-cols-2 gap-8 items-start"><div class="{PANEL}"><div class="{MICRO}" id="pb-chip">SIMULATED PLAYBACK</div><div class="mono text-[40px] mt-2" id="pb-reading">–</div><div class="text-[18px] mt-1" id="pb-next">–</div><div class="mono text-[28px] text-primary-container" id="pb-count">–</div><div class="vh" id="pb-sr" role="status"></div></div><div><div class="field-row"><button class="btn" id="pb-play" type="button">Play</button><button class="btn ghost" id="pb-reset" type="button">Restart</button><div class="field"><label for="pb-speed">Speed</label><select id="pb-speed"><option value="600">600× (10 min per second)</option><option value="1800" selected>1800×</option><option value="3600">3600× (1 hour per second)</option></select></div></div><p class="mt-3 text-[12px] text-on-surface-variant">Playback starts only when you press Play. It never moves on its own.</p></div></div>''') \
  + step("04", "compare", "Waqt vs Midnight — two temporal models", "Same events, same moment, different day boundaries.", '<div id="lab-compare"></div><h3 class="mt-10 mb-2 font-headline-sm text-[16px]">How long is the Waqt day?</h3><div id="lab-day"></div>') \
  + step("05", "build", "Build an Application", "Location → Waqt API → your application.", f'''<div class="eco" role="img" aria-label="Flow: Location, then the Waqt API, then your application"><div class="leaf" style="max-width:260px">Location<br><span class="muted mono" id="build-loc">lat, lon</span></div><div class="arrow" aria-hidden="true">↓</div><div class="core">WAQT API</div><div class="arrow" aria-hidden="true">↓</div><div class="leaf" style="max-width:260px">Your application</div></div><div class="tabs mt-6" role="tablist" aria-label="Language"><button role="tab" aria-selected="true" data-tab="curl">curl</button><button role="tab" aria-selected="false" data-tab="js">JavaScript</button><button role="tab" aria-selected="false" data-tab="py">Python (stdlib)</button></div><pre class="code" id="build-snippet" tabindex="0" aria-label="Code example"></pre><div class="mt-4 flex flex-wrap gap-3"><button class="btn" id="build-run" type="button">Run this request</button><a class="btn ghost" href="api.html">API reference</a></div><div id="build-out" class="{PANEL} mt-4" hidden aria-live="polite"></div>''')
page("lab.html", "Experience Lab", "Interactive Waqt demonstrations driven by the real API.", "apps", lab_body, LIVE, ["pages/lab"])
